// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 initialBalance, uint256 dummy) public {
        vm.assume(initialBalance > 0 && initialBalance <= address(this).balance);
        vm.assume(dummy >= 0);

        vm.deal(address(c), initialBalance);

        uint256 balanceBefore = address(c).balance;

        bool ok = true;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance < balanceBefore);
        } else {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}
